java.solution:
import java.util.*;

class Solution {
    static class Employee {
        String name;
        List<Employee> reports;
    }

    static Map<String, Integer> headcounts(Employee person) {
        Map<String, Integer> counts = new HashMap<>();
        visit(person, counts);
        return counts;
    }

    static int visit(Employee node, Map<String, Integer> counts) {
        int total = 1;
        for (Employee report : node.reports) total += visit(report, counts);
        counts.put(node.name, total);
        return total;
    }
}
